import base64, os

os.makedirs("frontend/public", exist_ok=True)

privacy_b64 = ""
terms_b64 = ""

with open("frontend/public/privacy.html", "wb") as f:
    f.write(base64.b64decode(privacy_b64))
with open("frontend/public/terms.html", "wb") as f:
    f.write(base64.b64decode(terms_b64))

print("privacy.html:", os.path.getsize("frontend/public/privacy.html"), "bytes")
print("terms.html:", os.path.getsize("frontend/public/terms.html"), "bytes")
print("Both files written successfully.")
